{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/h4-knowledge-pack-sonnet-t3/cell-lyP6zY/src/order.js","content":"/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */

import { COMMAND_TYPES, allowedTypes } from './machine.js';

const COMMAND_TYPE_SET = new Set(COMMAND_TYPES);

const REQUIRED_STRING_FIELDS = {
  addItem: ['sku'],
  removeItem: ['sku'],
  pay: [],
  pack: [],
  ship: ['carrier', 'tracking'],
  deliver: [],
  cancel: ['reason'],
  refund: [],
};

const MESSAGES = {
  CLOCK_REGRESSION: 'command timestamp precedes the order clock',
  BAD_STATE: 'command is not allowed in the current state',
  MISSING_FIELD: 'a required field is missing or empty',
  BAD_AMOUNT: 'an amount field is not an integer in range',
  DUPLICATE_SKU: 'that sku is already on the order',
  NO_SUCH_ITEM: 'that sku is not on the order',
  EMPTY_ORDER: 'an order with no items cannot be paid',
  AMOUNT_MISMATCH: 'the payment does not match the order total',
  REFUND_TOO_LARGE: 'the refund exceeds what remains to be returned',
};

/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  #commandResults = new Map();

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
  constructor(init) {
    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPE_SET.has(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    if (this.#commandResults.has(command.commandId)) {
      return { ...this.#commandResults.get(command.commandId), replayed: true };
    }

    const from = this.#state;

    if (command.at < this.#clockMs) {
      const result = this.#reject(command, 'CLOCK_REGRESSION', this.#clockMs, from, from);
      return result;
    }

    this.#clockMs = command.at;

    if (!allowedTypes(from).includes(command.type)) {
      return this.#reject(command, 'BAD_STATE', command.at, from, from);
    }

    const fieldError = this.#checkFields(command);
    if (fieldError) {
      return this.#reject(command, fieldError, command.at, from, from);
    }

    const businessError = this.#checkBusiness(command);
    if (businessError) {
      return this.#reject(command, businessError, command.at, from, from);
    }

    const to = this.#applyEffect(command);

    const seq = this.#audit.length + 1;
    this.#audit.push({
      seq,
      commandId: command.commandId,
      type: command.type,
      at: command.at,
      from,
      to,
      ok: true,
    });
    const result = { ok: true, state: to, seq, replayed: false };
    this.#commandResults.set(command.commandId, result);
    return result;
  }

  /** Record a rejection and return its result. */
  #reject(command, code, at, from, to) {
    const seq = this.#audit.length + 1;
    this.#audit.push({
      seq,
      commandId: command.commandId,
      type: command.type,
      at,
      from,
      to,
      ok: false,
      code,
    });
    const result = { ok: false, code, message: MESSAGES[code], state: to, seq, replayed: false };
    this.#commandResults.set(command.commandId, result);
    return result;
  }

  /** Validate the shape of a command's own fields; returns a code or null. */
  #checkFields(command) {
    for (const field of REQUIRED_STRING_FIELDS[command.type]) {
      if (typeof command[field] !== 'string' || command[field] === '') return 'MISSING_FIELD';
    }
    if (command.type === 'addItem') {
      if (!Number.isInteger(command.qty) || command.qty < 1) return 'BAD_AMOUNT';
      if (!Number.isInteger(command.unitPriceCents) || command.unitPriceCents < 0) return 'BAD_AMOUNT';
    }
    if (command.type === 'pay') {
      if (!Number.isInteger(command.amountCents) || command.amountCents < 0) return 'BAD_AMOUNT';
    }
    if (command.type === 'refund') {
      if (!Number.isInteger(command.amountCents) || command.amountCents < 1) return 'BAD_AMOUNT';
    }
    return null;
  }

  /** Validate business guards for a command; returns a code or null. */
  #checkBusiness(command) {
    if (command.type === 'addItem' && this.#items.has(command.sku)) return 'DUPLICATE_SKU';
    if (command.type === 'removeItem' && !this.#items.has(command.sku)) return 'NO_SUCH_ITEM';
    if (command.type === 'pay') {
      if (this.#items.size === 0) return 'EMPTY_ORDER';
      if (command.amountCents !== this.totalCents) return 'AMOUNT_MISMATCH';
    }
    if (command.type === 'refund') {
      if (command.amountCents > this.#paidCents - this.#refundedCents) return 'REFUND_TOO_LARGE';
    }
    return null;
  }

  /** Apply the effect of a valid command and return the resulting state. */
  #applyEffect(command) {
    switch (command.type) {
      case 'addItem':
        this.#items.set(command.sku, {
          sku: command.sku,
          qty: command.qty,
          unitPriceCents: command.unitPriceCents,
        });
        return this.#state;
      case 'removeItem':
        this.#items.delete(command.sku);
        return this.#state;
      case 'pay':
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        return this.#state;
      case 'pack':
        this.#state = 'packed';
        return this.#state;
      case 'ship':
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        return this.#state;
      case 'deliver':
        this.#deliveredAt = command.at;
        this.#state = 'delivered';
        return this.#state;
      case 'cancel':
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        return this.#state;
      case 'refund':
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents === this.#paidCents) this.#state = 'refunded';
        return this.#state;
      default:
        throw new Error(`unhandled command type: ${command.type}`);
    }
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}
"}

