/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */

import { COMMAND_TYPES, allowedTypes } from './machine.js';

const COMMAND_TYPE_SET = new Set(COMMAND_TYPES);

const REQUIRED_STRING_FIELDS = {
  addItem: ['sku'],
  removeItem: ['sku'],
  pay: [],
  pack: [],
  ship: ['carrier', 'tracking'],
  deliver: [],
  cancel: ['reason'],
  refund: [],
};

const MESSAGES = {
  CLOCK_REGRESSION: 'command timestamp precedes the order clock',
  BAD_STATE: 'command is not allowed in the current state',
  MISSING_FIELD: 'a required field is missing or empty',
  BAD_AMOUNT: 'an amount field is not an integer in range',
  DUPLICATE_SKU: 'that sku is already on the order',
  NO_SUCH_ITEM: 'that sku is not on the order',
  EMPTY_ORDER: 'an order with no items cannot be paid',
  AMOUNT_MISMATCH: 'the payment does not match the order total',
  REFUND_TOO_LARGE: 'the refund exceeds what remains to be returned',
};

/** An order and everything that has been asked of it. */
export class Order {
  #id;

diffs.oldText:
#deliveredAt = null;

/**
 * @param {{id: string, createdAt?: number}} init Identity and start time.
 */

diffs.newText:
#deliveredAt = null;

#commandResults = new Map();

/**
 * @param {{id: string, createdAt?: number}} init Identity and start time.
 */

diffs.oldText:
 * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
 */
