  throw new Error('not implemented');
}

/**
 * Build an order by applying a command list in order.
 *

diffs.newText:
 * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
 */
apply(command) {
  if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
  if (!COMMAND_TYPE_SET.has(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
  if (typeof command.commandId !== 'string' || command.commandId === '') {
    throw new TypeError('command must carry a non-empty commandId');
  }
  if (!Number.isInteger(command.at) || command.at < 0) {
    throw new TypeError('command must carry a non-negative integer at');
  }

  if (this.#commandResults.has(command.commandId)) {
    return { ...this.#commandResults.get(command.commandId), replayed: true };
  }

  const from = this.#state;

  if (command.at < this.#clockMs) {
    const result = this.#reject(command, 'CLOCK_REGRESSION', this.#clockMs, from, from);
    return result;
  }

  this.#clockMs = command.at;

  if (!allowedTypes(from).includes(command.type)) {
    return this.#reject(command, 'BAD_STATE', command.at, from, from);
  }

  const fieldError = this.#checkFields(command);
  if (fieldError) {
    return this.#reject(command, fieldError, command.at, from, from);
  }

  const businessError = this.#checkBusiness(command);
  if (businessError) {
    return this.#reject(command, businessError, command.at, from, from);
  }

  const to = this.#applyEffect(command);

  const seq = this.#audit.length + 1;
  this.#audit.push({
    seq,
    commandId: command.commandId,
    type: command.type,
    at: command.at,
    from,
    to,
    ok: true,
  });
  const result = { ok: true, state: to, seq, replayed: false };
  this.#commandResults.set(command.commandId, result);
  return result;
}

/** Record a rejection and return its result. */
#reject(command, code, at, from, to) {
  const seq = this.#audit.length + 1;
  this.#audit.push({
    seq,
    commandId: command.commandId,
    type: command.type,
    at,
    from,
    to,
    ok: false,
    code,
  });
  const result = { ok: false, code, message: MESSAGES[code], state: to, seq, replayed: false };
  this.#commandResults.set(command.commandId, result);
  return result;
}

/** Validate the shape of a command's own fields; returns a code or null. */
#checkFields(command) {
  for (const field of REQUIRED_STRING_FIELDS[command.type]) {
    if (typeof command[field] !== 'string' || command[field] === '') return 'MISSING_FIELD';
  }
  if (command.type === 'addItem') {
    if (!Number.isInteger(command.qty) || command.qty < 1) return 'BAD_AMOUNT';
    if (!Number.isInteger(command.unitPriceCents) || command.unitPriceCents < 0) return 'BAD_AMOUNT';
  }
  if (command.type === 'pay') {
    if (!Number.isInteger(command.amountCents) || command.amountCents < 0) return 'BAD_AMOUNT';
  }
  if (command.type === 'refund') {
    if (!Number.isInteger(command.amountCents) || command.amountCents < 1) return 'BAD_AMOUNT';
  }
  return null;
}

/** Validate business guards for a command; returns a code or null. */
#checkBusiness(command) {
  if (command.type === 'addItem' && this.#items.has(command.sku)) return 'DUPLICATE_SKU';
  if (command.type === 'removeItem' && !this.#items.has(command.sku)) return 'NO_SUCH_ITEM';
  if (command.type === 'pay') {
    if (this.#items.size === 0) return 'EMPTY_ORDER';
    if (command.amountCents !== this.totalCents) return 'AMOUNT_MISMATCH';
  }
  if (command.type === 'refund') {
    if (command.amountCents > this.#paidCents - this.#refundedCents) return 'REFUND_TOO_LARGE';
  }
  return null;
}

/** Apply the effect of a valid command and return the resulting state. */
#applyEffect(command) {
  switch (command.type) {
    case 'addItem':
      this.#items.set(command.sku, {
        sku: command.sku,
        qty: command.qty,
        unitPriceCents: command.unitPriceCents,
      });
      return this.#state;
    case 'removeItem':
      this.#items.delete(command.sku);
      return this.#state;
    case 'pay':
      this.#paidCents = command.amountCents;
      this.#state = 'paid';
      return this.#state;
    case 'pack':
      this.#state = 'packed';
      return this.#state;
    case 'ship':
      this.#shipment = { carrier: command.carrier, tracking: command.tracking };
      this.#state = 'shipped';
      return this.#state;
    case 'deliver':
      this.#deliveredAt = command.at;
      this.#state = 'delivered';
      return this.#state;
    case 'cancel':
      this.#refundedCents = this.#paidCents;
      this.#state = 'cancelled';
      return this.#state;
    case 'refund':
      this.#refundedCents += command.amountCents;
      if (this.#refundedCents === this.#paidCents) this.#state = 'refunded';
      return this.#state;
    default:
      throw new Error(`unhandled command type: ${command.type}`);
  }
}

/**
 * Build an order by applying a command list in order.
 *

